async function fetchUTXOs(address) {
    try {
        const response = await axios.get(
            `${BLOCKCYPHER_API_BASE}/addrs/${address}?unspentOnly=true`
        );
        return response.data.txrefs || [];
    } catch (error) {
        console.error("Error fetching UTXOs:", error);
        throw error;
    }
}

