    try {
        const response = await axios.get(`${BLOCKCYPHER_API_BASE}`);
        const mediumFeePerKb = response.data.medium_fee_per_kb;
        return Math.ceil(mediumFeePerKb / 1024);
    } catch (error) {
        console.error("Error estimating fee rate:", error);
        return 20; // Fallback
    }
}

// --- Transaction Creation (adapted from previous code) ---
async function createAndSendTransaction(toAddress, amountBTC, feeRate) {
    try {
        const keyPair = bitcoin.ECPair.fromWIF(PRIVATE_KEY_WIF, NETWORK);
        const { address } = bitcoin.payments.p2wpkh({
            pubkey: keyPair.publicKey,
            network: NETWORK,
        });

        const utxos = await fetchUTXOs(address);
        if (utxos.length === 0) {
            throw new Error("No UTXOs found for this address.");
        }

        const amount = Math.round(amountBTC * 1e8);
        const txb = new bitcoin.TransactionBuilder(NETWORK);

        let totalInput = 0;
        let inputCount = 0;

        for (const utxo of utxos) {
            txb.addInput(utxo.tx_hash, utxo.tx_output_n);
            totalInput += utxo.value;
            inputCount++;
            const estimatedSize = inputCount * 148 + 2 * 34 + 10;
            const estimatedFee = estimatedSize * feeRate;

            if (totalInput >= amount + estimatedFee) {
                break;
            }
        }

        const estimatedSize = inputCount * 148 + 2 * 34 + 10;
        const estimatedFee = estimatedSize * feeRate;

        if (totalInput < amount + estimatedFee) {
            throw new Error(
                `Insufficient funds.  Need ${amount + estimatedFee
                } satoshis, have ${totalInput}.`
            );
        }

        txb.addOutput(toAddress, amount);
        const change = totalInput - amount - estimatedFee;
        if (change > 546) {
            txb.addOutput(address, change);
        }

        for (let i = 0; i < inputCount; i++) {
            txb.sign(i, keyPair);
        }

        const rawTx = txb.build().toHex();
        const txHash = await broadcastTransaction(rawTx);

        // Analyze the created transaction
        analyzeTransaction(txHash, amountBTC, estimatedFee / 1e8); // Send in BTC

        return txHash;
    } catch (error) {
        console.error("Error creating/sending transaction:", error);
        throw error;
    }
}

// --- Transaction Broadcasting ---
async function broadcastTransaction(rawTx) {
    try {
        const response = await axios.post(`${BLOCKCYPHER_API_BASE}/txs/push`, {
            tx: rawTx,
        });
        return response.data.tx.hash;
    } catch (error) {
        console.error("Error broadcasting transaction:", error);
        throw error;
    }
}

