async function analyzeTransaction(txid, amount, fee) {
    try {
        const response = await axios.post(AI_MODEL_API, { txid, amount, fee });
        const risk = response.data.risk;
        const riskScore = response.data.risk_score;

        console.log(`🚀 AI Risk Analysis for ${txid}: ${risk} (Score: ${riskScore})`);

